INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (1, 1, 5, 'Tolles Buch, top Zustand!', '2026-03-20');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (2, 2, 4, 'Wie beschrieben, gerne wieder.', '2026-03-27');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (3, 3, 5, 'Etwas verspätete Abholung, sonst top.', '2026-04-03');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (4, 4, 4, 'Sehr freundlicher Austausch.', '2026-04-07');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (5, 5, 3, 'Buch war stärker abgenutzt als angegeben.', '2026-04-10');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (6, 6, 5, 'Perfekt fürs Wochenende.', '2026-04-21');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (7, 7, 4, 'Kommunikation war unkompliziert.', '2026-04-25');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (8, 8, 5, 'Würde ich weiterempfehlen.', '2026-05-02');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (9, 9, 4, 'Abholung hat gut geklappt.', '2026-05-09');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (10, 10, 3, 'Inhaltlich super, Einband leicht beschädigt.', '2026-05-09');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (11, 11, 5, 'Spannend bis zur letzten Seite.', '2026-05-20');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (12, 12, 5, 'Pünktliche Übergabe.', '2026-05-27');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (13, 13, 4, 'Genau das, was ich gesucht habe.', '2026-05-31');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (14, 14, 3, 'Zustand gut, Inhalt mittelmäßig.', '2026-06-07');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (15, 15, 5, 'Sehr nette Person, unkomplizierte Rückgabe.', '2026-06-10');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (16, 16, 4, 'Hat mir sehr gefallen.', '2026-06-18');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (17, 17, 3, 'Leider einige Notizen im Buch.', '2026-06-25');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (18, 18, 4, 'Schnelle Abwicklung.', '2026-07-02');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (19, 19, 5, 'Gerne wieder.', '2026-07-06');
INSERT INTO bewertung (bewertung_id, ausleihvorgang_id, sternebewertung, kommentar, erstellt_am) VALUES (20, 20, 5, 'Top!', '2026-07-09');
